"""Every number the project page quotes, regenerated by one command.

    PYTHONPATH=. uv run python bench/status.py            # seconds
    PYTHONPATH=. uv run python bench/status.py --full     # adds the slow benches

The portfolio carries a sourced metric per claim, and this is where those
sources funnel. Study numbers come from the corpus through the same functions
`study/analyse.py` uses; adoption numbers come from the same AST walk
`bench/adoption_diff.py` performs; the two slow measurements reuse
`bench/overhead.py`'s own helpers so neither script can drift from the other.
They sit behind --full because minutes of benchmarking do not belong in an
ordinary status check.
"""

from __future__ import annotations

import argparse
import gc
import pathlib
import statistics
import timeit
import tracemalloc

from opentelemetry.sdk.trace import TracerProvider
from opentelemetry.sdk.trace.export import (
    SimpleSpanProcessor,
    SpanExporter,
    SpanExportResult,
)

import spanlight
import spanlight._spans as spans_module
from bench.adoption_diff import REPO, SIBLING, SIBLING_SITES, SITES, adoption_lines
from study.analyse import DETECTORS, VERDICT, load, sessions, table

SESSIONS = 10_000


class Discard(SpanExporter):
    """Keeps nothing, so what is measured is Spanlight rather than the harness."""

    def export(self, spans) -> SpanExportResult:  # noqa: ARG002
        return SpanExportResult.SUCCESS

    def shutdown(self) -> None:
        pass


def study_rows() -> list[tuple[str, str]]:
    """Detector coverage and the silently-wrong share, Part B of the study."""
    runs = sessions(load())
    total = len(runs)

    rows = [
        (detector, f"{fired}/{total}")
        for detector in DETECTORS
        for fired in [sum(1 for r in runs.values() if detector in r["detections"])]
    ]
    wrong = sum(
        1
        for r in runs.values()
        for c in r["model_calls"]
        if c["attributes"].get(VERDICT) == "fail"
    )
    rows.append(("silently wrong verdicts", f"{wrong}/{total} ({wrong / total:.1%})"))
    return rows


def adoption_totals(
    sites: dict[str, str], base: pathlib.Path
) -> tuple[int, int, int]:
    statements = lines = 0
    for site in sites:
        counted, site_statements = adoption_lines(base / site)
        lines += len(counted)
        statements += site_statements
    return statements, lines, len(sites)


def overhead_rows() -> list[tuple[str, float, float]]:
    """The benchmark table via bench/overhead's helpers and constants, disabled
    first: set_tracer_provider is write-once."""
    import bench.overhead as overhead

    def measure(fn, setup=lambda: None):
        setup()
        timings = timeit.repeat(fn, repeat=overhead.REPEATS, number=overhead.ITERATIONS)
        per_call = [t / overhead.ITERATIONS * 1_000_000 for t in timings]
        return min(per_call), statistics.median(per_call)

    rows: list[tuple[str, float, float]] = []
    rows.append(("model_span, tracing disabled", *measure(overhead._model_span)))
    rows.append(("session, tracing disabled", *measure(overhead._session)))

    provider = TracerProvider()
    provider.add_span_processor(SimpleSpanProcessor(Discard()))
    from opentelemetry import trace

    trace.set_tracer_provider(provider)

    rows.append(("model_span, enabled", *measure(overhead._model_span)))
    rows.append(("tool_span, enabled", *measure(overhead._tool_span)))
    rows.append(
        (
            "tool_span, enabled, all detectors",
            *measure(overhead._tool_span, setup=overhead._register_detectors),
        )
    )
    return rows


def retained_bytes() -> int:
    """Residual bytes across 10k sessions, measured the way
    tests/spanlight/test_detector_state.py measures it: warmed baseline, a
    discard exporter rather than an accumulating one, gc before both snapshots.
    The test remains the gate; this is the regeneration."""
    from spanlight._detector_framework import registry
    from spanlight._detectors import (
        cost_ceiling_detector,
        loop_detector,
        silent_tool_failure_detector,
        watch_for_silent_failure,
    )

    provider = TracerProvider()
    provider.add_span_processor(SimpleSpanProcessor(Discard()))
    spans_module.get_tracer = lambda: provider.get_tracer("status")

    registry.clear_detectors()
    registry.register(loop_detector)
    registry.register(watch_for_silent_failure)
    registry.register(cost_ceiling_detector(1.0))
    registry.register(silent_tool_failure_detector, phase="session")

    def run(n: int) -> None:
        for i in range(n):
            with spanlight.session(), spanlight.tool_span("search", args={"q": f"q-{i}"}):
                pass

    run(500)
    gc.collect()
    tracemalloc.start()
    before = tracemalloc.take_snapshot()
    run(SESSIONS)
    gc.collect()
    after = tracemalloc.take_snapshot()
    tracemalloc.stop()
    return sum(s.size_diff for s in after.compare_to(before, "filename"))


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--full", action="store_true", help="add the minute-long benches")
    args = parser.parse_args()

    print("== field study (source: study/analyse.py) ==")
    table("", study_rows(), ("claim", "value"))

    print("\n== adoption (source: bench/adoption_diff.py) ==")
    statements, lines, count = adoption_totals(SITES, REPO)
    print(f"  this repo   {statements} statements, {lines} lines across {count} sites")
    print(f"  per site    {statements / count:.1f} statements, {lines / count:.1f} lines")
    if SIBLING.exists():
        sg_statements, sg_lines, sg_count = adoption_totals(SIBLING_SITES, SIBLING)
        print(
            f"  shipgate    {sg_statements} statements, {sg_lines} lines "
            f"across {sg_count} sites"
        )
        print(
            f"  per site    {sg_statements / sg_count:.1f} statements, "
            f"{sg_lines / sg_count:.1f} lines"
        )
    else:
        print(f"  shipgate not present beside this repo, skipped ({SIBLING})")

    if not args.full:
        print("\n== deferred to --full ==")
        print("  wall-clock overhead   bench/overhead.py methodology")
        print("  resident state        tests/spanlight/test_detector_state.py methodology")
        return

    print("\n== overhead (source: bench/overhead.py) ==")
    width = max(len(name) for name, _, _ in overhead_rows())
    for name, best, median in overhead_rows():
        print(f"  {name:{width}}   {best:8.2f}us {median:8.2f}us best-of-7 median")

    print("\n== detector state (source: tests/spanlight/test_detector_state.py) ==")
    grown = retained_bytes()
    per_session = grown / SESSIONS
    print(f"  {grown:,} bytes retained across {SESSIONS:,} sessions ({per_session:.1f}/session)")


if __name__ == "__main__":
    main()
